package com.app.eventmanagmentsystem.util;

import org.springframework.stereotype.Component;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.HexFormat;

/**
 * Utility for generating and hashing secure QR tokens.
 *
 * <p>Security rules:
 * <ul>
 *   <li>256-bit random token generated by {@link SecureRandom}.</li>
 *   <li>Only the SHA-256 hex digest is stored in the database.</li>
 *   <li>Raw tokens are never logged.</li>
 *   <li>Token comparison is done by hash (database lookup by hash is preferred
 *       over in-memory constant-time comparison for this use case).</li>
 * </ul>
 */
@Component
public class QrTokenUtil {

    private static final int TOKEN_BYTES = 32; // 256 bits
    private final SecureRandom secureRandom = new SecureRandom();

    /**
     * Generates a 256-bit secure random token and returns it as a hex string.
     * The caller must store only the SHA-256 hash of this value.
     */
    public String generateRawToken() {
        byte[] bytes = new byte[TOKEN_BYTES];
        secureRandom.nextBytes(bytes);
        return HexFormat.of().formatHex(bytes).toUpperCase();
    }

    /**
     * Computes the SHA-256 hex digest of the given token.
     */
    public String hashToken(String rawToken) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(rawToken.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}

